static inline double dgx_mlp_score(const float *features) {
    float a[64], b[64];
    for (int i = 0; i < DGX_MLP_N_FEATURES; ++i) {
        double x = isnan(features[i]) ? DGX_MLP_MEDIAN[i] : (double)features[i];
        double z = (x - DGX_MLP_MEAN[i]) / DGX_MLP_SCALE[i];
        a[i] = (float)(z > 5.0 ? 5.0 : (z < -5.0 ? -5.0 : z));  /* clip +/-5 SD */
    }
    for (int o = 0; o < 64; ++o) {
        float s = DGX_MLP_B0[o];
        for (int i = 0; i < 35; ++i) s += a[i] * DGX_MLP_W0[i * 64 + o];
        if (s < 0.0f) s = 0.0f;  /* ReLU */
        b[o] = s;
    }
    for (int i = 0; i < 64; ++i) a[i] = b[i];
    for (int o = 0; o < 32; ++o) {
        float s = DGX_MLP_B1[o];
        for (int i = 0; i < 64; ++i) s += a[i] * DGX_MLP_W1[i * 32 + o];
        if (s < 0.0f) s = 0.0f;  /* ReLU */
        b[o] = s;
    }
    for (int i = 0; i < 32; ++i) a[i] = b[i];
    for (int o = 0; o < 1; ++o) {
        float s = DGX_MLP_B2[o];
        for (int i = 0; i < 32; ++i) s += a[i] * DGX_MLP_W2[i * 1 + o];
        b[o] = s;
    }
    return 1.0 / (1.0 + exp(-(double)b[0]));
}
